package com.atlasiq.pr;
import com.atlasiq.intelligence.ArchitectureDiff;import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class ArchitecturePolicyEngine {public List<PrIntelligenceReport.PolicyViolation> evaluate(ArchitectureDiff d){List<PrIntelligenceReport.PolicyViolation> out=new ArrayList<>();for(QirNode n:d.addedNodes()){if("database".equals(n.type())&&"production".equalsIgnoreCase(String.valueOf(n.metadata().get("environment"))))out.add(new PrIntelligenceReport.PolicyViolation("production-database-review",n.id(),"New production database requires architecture review","high"));if("api-endpoint".equals(n.type())&&n.name().toLowerCase().contains("/internal/"))out.add(new PrIntelligenceReport.PolicyViolation("internal-api-review",n.id(),"New internal API surface requires ownership review","medium"));}return List.copyOf(out);}}
